document.addEventListener("DOMContentLoaded",function(){function setImageSize(image,width,height){image.style.width=width+"px";image.style.height=height+"px"}function loadImage(image){var src=image.getAttribute("data-src");if(src){var tempImg=new Image;tempImg.src=src;tempImg.onload=function(){image.src=src;setImageSize(image,tempImg.width,tempImg.height)}}}var lazyImages=document.querySelectorAll("img[data-src]");if("IntersectionObserver"in window){var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){var image=entry.target;loadImage(image);observer.unobserve(image)}})});lazyImages.forEach(function(image){observer.observe(image)})}else{lazyImages.forEach(function(image){loadImage(image)})}var lazyBgItems=document.querySelectorAll("[data-bg]");function loadBgImages(){lazyBgItems.forEach(function(item){var bg=item.getAttribute("data-bg");item.style.backgroundImage="url("+bg+")"})}if("IntersectionObserver"in window){var bgObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){var item=entry.target;var bg=item.getAttribute("data-bg");item.style.backgroundImage="url("+bg+")";bgObserver.unobserve(item)}})});lazyBgItems.forEach(function(item){bgObserver.observe(item)})}else{loadBgImages()}});